class Solution:
    def backspaceCompare(self, s: str, t: str) -> bool:
        def next_valid(string: str, i: int) -> int:
            skip = 0
            while i >= 0:
                if string[i] == "#":
                    skip += 1
                elif skip > 0:
                    skip -= 1
                else:
                    break                        # a character that survives
                i -= 1
            return i

        i, j = len(s) - 1, len(t) - 1
        while i >= 0 or j >= 0:
            i, j = next_valid(s, i), next_valid(t, j)
            if i >= 0 and j >= 0:
                if s[i] != t[j]:
                    return False
            elif i >= 0 or j >= 0:               # one string ran out first
                return False
            i -= 1
            j -= 1
        return True
